# ---------------------------------------------------------------------------
# Fake local Ollama
# ---------------------------------------------------------------------------
class FakeOllama:
    """Minimal /api/tags + /api/chat server. ``responder(payload) -> str`` produces message content."""

    def __init__(self, models=(MODEL,)) -> None:
        self.models = list(models)
        self.requests: list[dict] = []
        self.responder = lambda payload: '{"operation": "unsupported"}' if payload.get("format") else "Facts: none."
        self.redirect = False
        outer = self

        class Handler(BaseHTTPRequestHandler):
            def log_message(self, *a):  # silence
                pass

            def _send(self, code: int, obj: dict, headers: dict | None = None) -> None:
                body = json.dumps(obj).encode()
                self.send_response(code)
                for k, v in (headers or {}).items():
                    self.send_header(k, v)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)

            def do_GET(self):
                if outer.redirect:
                    return self._send(302, {}, {"Location": "http://example.com/api/tags"})
                if self.path == "/api/tags":
                    return self._send(200, {"models": [{"name": m} for m in outer.models]})
                self._send(404, {"error": "not found"})

            def do_POST(self):
                payload = json.loads(self.rfile.read(int(self.headers["Content-Length"])) or b"{}")
                outer.requests.append(payload)
                if self.path != "/api/chat":
                    return self._send(404, {"error": "not found"})
                if payload.get("model") not in outer.models:
                    return self._send(404, {"error": f"model '{payload.get('model')}' not found"})
                self._send(200, {"message": {"role": "assistant", "content": outer.responder(payload)}})

        self.server = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        self.url = f"http://127.0.0.1:{self.server.server_address[1]}"
        threading.Thread(target=self.server.serve_forever, daemon=True).start()

    def close(self) -> None:
        self.server.shutdown()
        self.server.server_close()


def _free_port() -> int:
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        return s.getsockname()[1]


# ---------------------------------------------------------------------------
# Shared fixture: synthetic DB + hardened copy + chat service
# ---------------------------------------------------------------------------
class ChatBase(AnalyticsTestBase):
    @classmethod
    def setUpClass(cls) -> None:
        super().setUpClass()
        cls.chat_db = cls.tmp / "chat_copy.duckdb"
        shutil.copy(cls.db_path, cls.chat_db)
        cls.con = sq.open_hardened_connection(cls.chat_db)
        cls.views = approved_views(cls.con)
        cls.mapping = resolve_mapping(cls.mapping_raw, cls.views)
        cls.fake = FakeOllama()

    @classmethod
    def tearDownClass(cls) -> None:
        cls.con.close()
        cls.fake.close()
        super().tearDownClass()

    def service(self, *, llm: OllamaClient | None = None, use_llm: bool = False, mapping=None,
                **settings) -> cs.ChatService:
        st = cs.ChatSettings(use_llm=use_llm, **settings)
        return cs.ChatService(self.con, mapping or self.mapping, llm, salt=self.salt,
                              approved_views=set(self.views), settings=st)

    def assert_no_secrets(self, obj) -> None:
        text = json.dumps(obj)
        for s in SECRETS:
            self.assertNotIn(s, text, f"synthetic value {s!r} leaked into the response")


# ---------------------------------------------------------------------------
# LLM service
# ---------------------------------------------------------------------------
class TestLLMService(unittest.TestCase):
    def test_non_local_endpoints_are_refused(self) -> None:
        for url in ("http://example.com:11434", "http://10.0.0.5:11434", "https://api.openai.com", "ftp://127.0.0.1"):
            with self.assertRaises(ValueError):
                OllamaClient(url, MODEL)

    def test_connection_failure(self) -> None:
        client = OllamaClient(f"http://127.0.0.1:{_free_port()}", MODEL, timeout=2)
        st = client.status()
        self.assertFalse(st["reachable"])
        # Windows retries refused localhost connections for ~2 s, so a short timeout may report "timeout".
        self.assertIn(st["error"], ("connection_error", "timeout"))
        self.assertFalse(st["cloud_fallback"])
        with self.assertRaises(LLMUnavailable) as ctx:
            client.chat([{"role": "user", "content": "hi"}])
        self.assertIn(ctx.exception.code, ("connection_error", "timeout"))

    def test_model_missing_and_available(self) -> None:
        fake = FakeOllama(models=("other-model:7b",))
        try:
            client = OllamaClient(fake.url, MODEL, timeout=5)
            st = client.status()
            self.assertTrue(st["reachable"])
            self.assertFalse(st["model_available"])
            with self.assertRaises(LLMUnavailable) as ctx:
                client.chat([{"role": "user", "content": "hi"}])
            self.assertEqual(ctx.exception.code, "model_missing")
            fake.models.append(MODEL)
            ok = OllamaClient(fake.url, MODEL, timeout=5)
            self.assertTrue(ok.status()["model_available"])
            self.assertEqual(ok.chat([{"role": "user", "content": "hi"}]), "Facts: none.")
        finally:
            fake.close()

    def test_proxy_env_is_ignored_and_redirects_refused(self) -> None:
        fake = FakeOllama()
        old = {k: os.environ.get(k) for k in ("HTTP_PROXY", "http_proxy")}
        try:
            os.environ["HTTP_PROXY"] = os.environ["http_proxy"] = "http://203.0.113.1:9"   # unreachable proxy
            self.assertTrue(OllamaClient(fake.url, MODEL, timeout=5).status()["reachable"])
            fake.redirect = True
            self.assertFalse(OllamaClient(fake.url, MODEL, timeout=5).status()["reachable"])
        finally:
            for k, v in old.items():
                if v is None:
                    os.environ.pop(k, None)
                else:
                    os.environ[k] = v
            fake.close()


# ---------------------------------------------------------------------------
# Safe query layer
# ---------------------------------------------------------------------------
class TestSafeQuery(ChatBase):
    ATTACKS = [
        "DROP TABLE raw_holes",
        "SELECT 1; DROP TABLE raw_holes",
        "SELECT count(*) FROM tv_holes; DELETE FROM raw_holes",
        "SELECT * FROM raw_holes",
        "SELECT * FROM meta_ingestion_files",
        "SELECT * FROM information_schema.tables",
        "SELECT * FROM main.tv_holes",
        "SELECT * FROM duckdb_tables()",
        "SELECT * FROM read_csv('data/holes.jsonl')",
        "SELECT * FROM read_json_auto('data/x.jsonl')",
        "SELECT * FROM 'data/holes.jsonl'",
        "SELECT * FROM glob('data/*')",
        "SELECT getenv('PATH')",
        "COPY tv_holes TO 'out.csv'",
        "ATTACH 'other.duckdb' AS o",
        "INSTALL httpfs",
        "PRAGMA table_info('raw_holes')",
        "SET enable_external_access = true",
        "WITH x AS (SELECT * FROM raw_holes) SELECT * FROM x",
        "SELECT * FROM tv_holes WHERE 1=1 -- hidden",
        "SELECT * FROM tv_holes /* c */",
        "SELECT * FROM (SELECT * FROM raw_holes) s",
        "SELECT * FROM tv_holes UNION ALL SELECT * FROM raw_holes",
        "CREATE VIEW x AS SELECT 1",
        "UPDATE raw_holes SET payload = NULL",
        "SELECT 'unterminated",
        "EXPLAIN SELECT * FROM tv_holes",
        "SELECT * FROM range(10)",
        "",
    ]

    def test_attacks_are_rejected(self) -> None:
        for sql in self.ATTACKS:
            with self.subTest(sql=sql):
                with self.assertRaises(sq.UnsafeQueryError):
                    sq.validate_select(self.con, sql, self.views)
        with db.db_connection(self.db_path, read_only=True) as con:   # original DB untouched
            self.assertIn("raw_holes", db.list_tables(con))

    def test_allowed_queries_and_row_limit(self) -> None:
        vq = sq.validate_select(self.con, "SELECT count(*) AS n FROM tv_holes;", self.views)
        self.assertEqual(vq.tables, frozenset({"tv_holes"}))
        res = sq.execute_select(self.con, vq)
        self.assertEqual(res.rows[0][0], len(self.data["holes"]))
        cte = sq.validate_select(self.con, 'WITH h AS (SELECT "rigId" FROM tv_holes) SELECT count(*) FROM h', self.views)
        self.assertEqual(sq.execute_select(self.con, cte).rows[0][0], len(self.data["holes"]))
        many = sq.validate_select(self.con, "SELECT _record_key FROM tv_holes WHERE \"depthM\" > ?", self.views)
        res = sq.execute_select(self.con, many, [0], row_limit=7)
        self.assertEqual(len(res.rows), 7)
        self.assertTrue(res.truncated)

    def test_timeout_interrupts_query(self) -> None:
        heavy = sq.validate_select(self.con, "SELECT count(*) FROM tv_holes a, tv_holes b, tv_holes c", self.views)
        with self.assertRaises(sq.QueryTimeout):
            sq.execute_select(self.con, heavy, timeout=0.05)

    def test_connection_is_hardened(self) -> None:
        for stmt in ("SET enable_external_access = true", "CREATE TABLE x (a INT)",
                     "SELECT * FROM read_csv('x.csv')"):
            with self.subTest(stmt=stmt):
                with self.assertRaises(duckdb.Error):
                    self.con.execute(stmt)


